<?php
declare(strict_types=1);require_once __DIR__.'/../../app/bootstrap.php';$admin=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'pending');$expertId=(int)($_POST['expert_user_id']??0);$notes=trim((string)($_POST['admin_notes']??''));if(!in_array($status,['pending','assigned','closed','cancelled'],true)){flash_set('err','Invalid status.');}else{$assigned=$expertId>0?$expertId:null;if($status==='assigned'&&!$assigned){flash_set('err','Choose a verified expert before assigning.');redirect('/admin/expert-requests.php');}$up=db()->prepare('UPDATE expert_requests SET status=?,assigned_expert_user_id=?,admin_notes=?,assigned_at=CASE WHEN ?=\'assigned\' THEN NOW() ELSE assigned_at END WHERE id=?');$up->execute([$status,$assigned,$notes?:null,$status,$id]);flash_set('ok','Expert request updated.');}redirect('/admin/expert-requests.php');}
$rows=db()->query('SELECT er.*,b.full_name buyer_name,b.phone buyer_phone,r.name region_name,d.name district_name,w.name ward_name FROM expert_requests er JOIN users b ON b.id=er.buyer_user_id JOIN locations_regions r ON r.code=er.region_code JOIN locations_districts d ON d.region_code=er.region_code AND d.code=er.district_code JOIN locations_wards w ON w.region_code=er.region_code AND w.district_code=er.district_code AND w.code=er.ward_code ORDER BY FIELD(er.status,\'pending\',\'assigned\',\'closed\',\'cancelled\'),er.id DESC')->fetchAll();
$experts=db()->query("SELECT id,full_name,expert_type,region_code,district_code,ward_code FROM users WHERE role='expert' AND verification_status='verified' AND is_active=1 ORDER BY expert_type,full_name")->fetchAll();ob_start(); ?>
<div class="card pad reveal"><div class="kicker">Admin</div><h1>Expert matching</h1><p class="sub">Review buyer needs and manually assign a verified professional.</p><div class="request-grid"><?php if(!$rows):?><p class="sub">No expert requests.</p><?php endif;?><?php foreach($rows as $row):?><article class="request-card"><span class="pill <?= $row['status']==='pending'?'warn':'ok' ?>"><?= h((string)$row['status']) ?></span><h3><?= h(ucwords(str_replace('_',' ',(string)$row['expert_type']))) ?></h3><p><strong><?= h((string)$row['buyer_name']) ?></strong> · <?= h((string)$row['buyer_phone']) ?></p><p class="sub"><?= h((string)$row['region_name']) ?> · <?= h((string)$row['district_name']) ?> · <?= h((string)$row['ward_name']) ?></p><p><?= nl2br(h((string)$row['description'])) ?></p><form method="post" class="stack"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div><label>Verified expert</label><select name="expert_user_id"><option value="">Not assigned</option><?php foreach($experts as $expert):if($expert['expert_type']!==$row['expert_type'])continue;?><option value="<?= (int)$expert['id'] ?>" <?= (int)$row['assigned_expert_user_id']===(int)$expert['id']?'selected':'' ?>><?= h((string)$expert['full_name']) ?></option><?php endforeach;?></select></div><div><label>Status</label><select name="status"><?php foreach(['pending','assigned','closed','cancelled'] as $status):?><option value="<?= $status ?>" <?= $row['status']===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach;?></select></div><div><label>Admin update</label><textarea name="admin_notes"><?= h((string)$row['admin_notes']) ?></textarea></div><button class="btn" type="submit">Save match</button></form></article><?php endforeach;?></div></div>
<?php $content=ob_get_clean();$title='Expert matching. Ardhi Way';require __DIR__.'/../_layout.php';
